<template>
 <view class="growth-tools">
  <view v-if="incoming" class="growth-bar"><button tabindex="0" v-if="incoming" @click="showShared">{{ $t("ui.view_shared_listing") }}</button></view>
  <view v-if="activitiesVisible" class="activities-page" role="region" :aria-label="$t(&quot;nav.events&quot;)">
   <view class="activities-head"><view><b>{{ $t("nav.events") }}</b><text v-if="reservedCount" class="reservation-count">{{ $t("ui.reserved") }} {{reservedCount}}</text></view><button tabindex="0" :disabled="working" @click="loadActivities">{{working?$t("ui.refreshing"):$t("action.refresh")}}</button></view>
     <view class="note">{{ $t("ui.times_use_your_device_s_time_zone_return_at") }}</view>
     <view v-if="!activities.length" class="activities-empty">{{working?$t("ui.loading_events"):$t("ui.no_events_available_yet")}}</view>
     <view class="activity-grid"><view v-for="a in activities" :key="a.id" class="activity"><view class="activity-top"><b>{{a.title}}</b><text class="status" :class="{accent:a.mine}">{{a.status==='cancelled'?$t("ui.cancelled"):a.mine?$t("ui.reserved"):a.reserved+'/'+a.capacity}}</text></view><view class="time">{{time(a.starts_at)}} — {{time(a.ends_at)}}</view><view class="tags"><text v-for="v in a.segment" :key="v">{{$t(platformNames[v]||v)}}</text></view><view class="actions"><button tabindex="0" v-if="!a.mine&&a.status!=='cancelled'" class="primary" :disabled="working||a.reserved>=a.capacity" @click="reserve(a)">{{a.reserved>=a.capacity?$t("ui.fully_booked"):$t("ui.reserve_a_slot")}}</button><button tabindex="0" v-if="a.mine" :disabled="working" @click="reserve(a,true)">{{ $t("ui.cancel_reservation") }}</button><button tabindex="0" v-if="a.status!=='cancelled'&&now>=Date.parse(a.starts_at)&&now<Date.parse(a.ends_at)" class="primary" @click="enterActivity(a)">{{ $t("ui.set_conditions_find_teammates") }}</button><text v-else-if="a.mine&&a.status!=='cancelled'" class="note">{{ $t("ui.return_when_the_event_starts") }}</text></view></view>
   </view>
  </view>

  <app-toast v-if="toast&&!panel" :message="toast.message" :type="toast.type"/>
  <view v-if="panel" class="overlay" @click.self="close" @keydown.esc="close"><view class="dialog" role="dialog" aria-modal="true" :aria-label="panelTitle" tabindex="-1" @keydown.tab="trapFocus">
  <app-toast v-if="toast" :message="toast.message" :type="toast.type"/>
   <view class="dialog-head"><b>{{$t(panelTitle)}}</b><button tabindex="0" class="close" :aria-label="$t(&quot;action.close&quot;)" @click="close">×</button></view>
   <view class="dialog-body">
    <view v-if="error" class="error" role="alert">{{$error(error)}}</view>
    <template v-if="panel==='share'"><view class="note">{{ $t("ui.share_the_link_with_another_player_they_can_apply") }}</view><view class="link-input"><text selectable>{{link}}</text></view><button tabindex="0" class="primary" @click="copyLink">{{copied?$t("ui.copied"):$t("ui.copy_listing_link")}}</button><view class="note">{{ $t("ui.the_link_expires_when_the_listing_ends") }}</view></template>
    <template v-if="panel==='incoming'">
     <view v-if="shared" class="shared-card"><view class="name">{{shared.profile.nickname}}</view><view class="tags"><text>{{$t(shared.profile.goal)}}</text><text>{{shared.profile.region}}</text><text>{{$t(shared.profile.language)}}</text><text>{{$t(shared.profile.voice)}}</text><text>{{$t(platformNames[shared.profile.platform])}}</text></view><view class="tags"><text v-for="m in shared.profile.maps" :key="m.map">{{$t(m.map)}} · {{$t(m.difficulty)}}</text></view><view class="detail">{{ $t("ui.your_skill") }} {{shared.profile.strength_score}} {{ $t("ui.playstyle") }} {{shared.profile.style}}<br/>{{ $t("ui.teammate_skill") }} {{shared.profile.strength_min}}–{{shared.profile.strength_max}} {{ $t("ui.playstyle") }} {{shared.profile.partner_style_min}}–{{shared.profile.partner_style_max}}</view><view v-if="shared.profile.goal!=='goal.budget_run'" class="detail">{{ $t("ui.your_gear_helmet") }}{{shared.profile.helmet}} {{ $t("ui.armor_423") }}{{shared.profile.armor}} {{ $t("ui.ammo_424") }}{{shared.profile.ammo}}<br/>{{ $t("ui.teammate_minimum_helmet") }}{{shared.profile.partner_helmet_min}} {{ $t("ui.armor_423") }}{{shared.profile.partner_armor_min}} {{ $t("ui.ammo_424") }}{{shared.profile.partner_ammo_min}}</view><view v-if="shared.profile.tasks?.length" class="tags"><text v-for="task in shared.profile.tasks" :key="task">{{$t(task)}}</text></view><view class="note">{{shared.is_me?$t("ui.this_is_your_own_listing"):!shared.online?$t("ui.player_is_offline_apply_when_they_return"):$t("ui.player_online")}} {{ $t("ui.expires") }} {{time(shared.expires_at)}}</view>
      <view v-if="shared.assessment&&!shared.is_me" class="tags checks"><text v-for="c in shared.assessment.checks" :key="c.label" :class="{conflict:!c.ok}">{{c.ok?'✓':'×'}} {{$t(c.label)}}</text><text v-for="c in shared.assessment.hard_conflicts" :key="c" class="conflict">× {{$t(c)}}</text></view>
      <view class="actions"><button tabindex="0" v-if="shared.can_invite" class="primary" :disabled="working" @click="inviteShared">{{ $t("ui.request_to_team_up") }}</button><button tabindex="0" v-if="!shared.is_me" @click="editOwn">{{activeTicket?$t("ui.view_your_conditions"):$t("ui.enter_your_conditions")}}</button><button tabindex="0" :disabled="working" @click="loadShared">{{ $t("action.refresh") }}</button></view>
     </view><view v-else-if="working" class="note">{{ $t("ui.loading_listing") }}</view>
    </template>
    <template v-if="panel==='operations'">
     <template v-if="!authorized"><view class="note">{{ $t("ui.paste_your_operator_key_or_configuration_line_it_is") }}</view><input v-model="operatorKey" password :placeholder="$t(&quot;ui.operator_key&quot;)"/><button tabindex="0" class="primary" :disabled="working||!operatorKey" @click="loadMetrics">{{ $t("ui.view_metrics") }}</button></template>
     <template v-else>
      <view class="metrics"><view><text>{{ $t("ui.visit_publish") }}</text><b>{{pct(metrics.publication_rate)}}</b><small>{{metrics.publishers}} / {{metrics.visitors}} {{ $t("ui.players") }}</small></view><view><text>{{ $t("ui.publish_both_confirm") }}</text><b>{{pct(metrics.confirmation_rate)}}</b><small>{{metrics.confirmed_requests}} / {{metrics.requests}} {{ $t("ui.listings") }}</small></view><view><text>{{ $t("ui.reported_playing_together") }}</text><b>{{pct(metrics.reported_play_rate)}}</b><small>{{metrics.played_requests}} / {{metrics.feedback_requests}} {{ $t("ui.responses") }}</small></view><view><text>{{ $t("ui.repeat_publishing") }}</text><b>{{pct(metrics.repeat_publication_rate)}}</b><small>{{metrics.repeat_publishers}} / {{metrics.publishers}} {{ $t("ui.players") }}</small></view></view>
      <view class="note">{{ $t("ui.confirmed_within_5_minutes") }} {{metrics.confirmed_within_5min}} / {{metrics.requests}} {{ $t("ui.listings_median_confirmation_time") }} {{metrics.median_confirm_seconds??'—'}} {{ $t("unit.seconds") }}<br/>{{ $t("ui.feedback_coverage") }} {{pct(metrics.feedback_coverage)}} {{ $t("ui.would_team_up_again") }} {{pct(metrics.willing_again_rate)}}<br/>{{ $t("ui.tracking_since") }} {{metrics.since?time(metrics.since):$t("ui.no_visits_yet")}}<br/>{{$t(metrics.notice)}}</view><button tabindex="0" :disabled="working" @click="loadMetrics">{{ $t("ui.refresh_metrics") }}</button>
      <details class="create-activity"><summary>{{ $t("ui.create_event") }}</summary><label>{{ $t("ui.event_name") }}<input v-model="eventForm.title" maxlength="48" :placeholder="$t(&quot;ui.e_g_friday_loot_extract&quot;)"/></label><view class="activity-start-field"><text>{{ $t("ui.start_time_device_time_zone") }}</text><activity-datetime-picker v-model="eventForm.local_time"/></view><view class="form-grid"><label>{{ $t("ui.duration_minutes") }}<input v-model.number="eventForm.duration_minutes" type="number"/></label><label>{{ $t("ui.reservation_limit") }}<input v-model.number="eventForm.capacity" type="number"/></label></view><view class="form-grid"><label v-for="f in segmentFields" :key="f.key">{{$t(f.label)}}<dark-select v-model="eventForm[f.key]" :options="f.options" :label="f.label"/></label></view><button tabindex="0" class="primary" :disabled="working" @click="createActivity">{{working?$t("status.publishing"):$t("ui.publish_event")}}</button></details>
      <view v-for="a in activities" :key="a.id" class="activity"><b>{{a.title}}</b><view class="note">{{time(a.starts_at)}} · {{a.reserved}} {{ $t("ui.reservations") }}</view><button tabindex="0" v-if="a.status!=='cancelled'" :disabled="working" @click="closeActivity(a)">{{closing===a.id?$t("ui.confirm_event_cancellation"):$t("ui.cancel_event")}}</button></view>
     </template>
    </template>
   </view>
  </view></view>
 </view>
</template>
<script setup>
import {formatDate} from '../i18n/index.js'
import AppToast from './app-toast.vue'
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue'
import DarkSelect from './dark-select.vue'
import ActivityDatetimePicker from './activity-datetime-picker.vue'
import {authRequest,sessionToken} from '../utils/pilot-session.js'
import {API_BASE} from '../config.js'
import {shareCode,shareUrl,localActivityTime,operatorCredential,activityDateDefault,operationsErrorMessage} from '../utils/growth-ui.js'
const props=defineProps({ticket:Object,activeTicket:Boolean,activitiesVisible:Boolean})
const emit=defineEmits(['matched','edit','activity'])
const panel=ref(''),error=ref(''),working=ref(false),shared=ref(null),link=ref(''),copied=ref(false),activities=ref([]),now=ref(Date.now()),incoming=ref(typeof window==='undefined'?'':shareCode(window.location.hash))
const operatorKey=ref(''),authorized=ref(false),metrics=ref({}),closing=ref(null)
const toast=ref(null)
let toastTimer=null
function notify(message,type='success'){clearTimeout(toastTimer);toast.value={message,type};toastTimer=setTimeout(()=>{toast.value=null},type==='error'?6000:3500)}
const eventForm=ref({title:'',local_time:activityDateDefault(),duration_minutes:120,capacity:30,region:'SEA',platform:'PC',language:'language.zh',goal:'goal.loot_extract'})
const segmentFields=[{key:'region',label:'profile.region',options:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'profile.platform',options:['PC','Console','Mobile']},{key:'language',label:'ui.language',options:['language.zh','language.en','language.ja']},{key:'goal',label:'ui.game_mode',options:['goal.missions','goal.budget_run','goal.loot_extract','goal.aggressive']}]
const platformNames={PC:'ui.pc',Console:'ui.console',Mobile:'ui.mobile'}
const reservedCount=computed(()=>activities.value.filter(a=>a.mine&&a.status!=='cancelled').length)
const panelTitle=computed(()=>({share:'ui.share_listing',incoming:'ui.player_listing',operations:'ui.operations'}[panel.value]||''))
const time=v=>formatDate(v,{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})
const pct=v=>v==null?'—':v+'%'
let generation=0,oldOverflow='',oldRootOverflow='',lastFocus=null,locked=false,openedIncoming=false
async function perform(fn,{toastError=false}={}){if(working.value)return;working.value=true;error.value='';const id=generation,identity=sessionToken.value;try{const value=await fn();return id===generation&&identity===sessionToken.value?value:undefined}catch(e){if(id===generation){if(toastError)notify(e.message,'error');else error.value=e.message}}finally{if(id===generation)working.value=false}}
function close(){if(working.value)return;panel.value='';operatorKey.value='';authorized.value=false;metrics.value={};closing.value=null;error.value=''}
function open(value){error.value='';panel.value=value}
watch(panel,async (value,old)=>{if(typeof document==='undefined')return;if(value&&!old){lastFocus=document.activeElement;oldOverflow=document.body.style.overflow;oldRootOverflow=document.documentElement.style.overflow;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';locked=true;await nextTick();document.querySelector('.growth-tools .dialog')?.focus()}else if(!value&&locked){document.body.style.overflow=oldOverflow;document.documentElement.style.overflow=oldRootOverflow;locked=false;lastFocus?.focus?.()}})
function trapFocus(e){const els=[...document.querySelectorAll('.growth-tools .dialog [tabindex="0"],.growth-tools .dialog input,.growth-tools .dialog summary')].filter(el=>!el.hasAttribute('disabled')&&el.getClientRects().length);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement?.classList.contains('dialog'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
async function makeShare(){const result=await perform(()=>authRequest('shares',{}));if(result){link.value=shareUrl(window.location,result.code);copied.value=false;open('share')}}
function copyLink(){uni.setClipboardData({data:link.value,showToast:false,success:()=>{copied.value=true},fail:()=>{error.value='ui.copy_failed_select_and_copy_the_link_manually'}})}
async function loadShared(){shared.value=null;const result=await perform(()=>authRequest('shares/'+encodeURIComponent(incoming.value)));if(result)shared.value=result}
async function showShared(){open('incoming');await loadShared()}
async function inviteShared(){const result=await perform(()=>authRequest('shares/'+encodeURIComponent(incoming.value)+'/invite',{}));if(result){close();emit('matched',result)}}
function editOwn(){close();emit('edit')}
async function loadActivities(){const result=await perform(()=>authRequest('activities'),{toastError:true});if(result){activities.value=result.items;now.value=Date.parse(result.server_now)}}
watch(()=>props.activitiesVisible,visible=>{if(visible&&sessionToken.value)loadActivities()},{immediate:true})
async function reserve(a,cancel=false){if(working.value)return;const result=await perform(()=>authRequest('activities/'+a.id+(cancel?'/cancel':'/reserve'),{}),{toastError:true});if(result){notify(cancel?'ui.reservation_cancelled':'ui.reservation_confirmed');await loadActivities()}}
function enterActivity(a){if(props.activeTicket){notify('ui.finish_or_cancel_your_current_listing_before_joining_an','error');return}close();emit('activity',a.segment)}
function admin(path,data){return new Promise((resolve,reject)=>uni.request({url:API_BASE+'/pilot/operations/'+path,timeout:15000,method:data===undefined?'GET':'POST',data,header:{Authorization:'Bearer '+operatorCredential(operatorKey.value)},success:r=>r.statusCode<400?resolve(r.data):reject(new Error(operationsErrorMessage(r.statusCode,r.data))),fail:failure=>reject(new Error(failure?.errMsg?.includes('timeout')?'ui.request_timed_out_please_try_again_later':'ui.connection_failed_please_try_again_later'))}))}
async function loadMetrics(){const key=operatorCredential(operatorKey.value);if(key==='PILOT_METRICS_TOKEN'||key.length<32){error.value='ui.enter_the_complete_value_after_pilot_metrics_token';return}const result=await perform(()=>admin('metrics'));if(result){metrics.value=result;authorized.value=true;await loadActivities()}}
async function createActivity(){
 if(working.value)return
 let starts
 try{starts=localActivityTime(eventForm.value.local_time)}catch(e){notify(e.message,'error');return}
 const identity=sessionToken.value
 const {local_time,...data}=eventForm.value
 const result=await perform(()=>admin('activities',{...data,starts_at:starts}))
 if(identity!==sessionToken.value)return
 if(result){eventForm.value.title='';notify('ui.event_published');await loadActivities()}
 else {const message=error.value||'ui.could_not_publish_the_event_please_try_again_later';error.value='';notify(message,'error')}
}
async function closeActivity(a){if(working.value)return;if(closing.value!==a.id){closing.value=a.id;return}const identity=sessionToken.value;const result=await perform(()=>admin('activities/'+a.id+'/close',{}));if(identity!==sessionToken.value)return;if(result){closing.value=null;notify('ui.event_cancelled');await loadActivities()}else{const message=error.value||'ui.could_not_cancel_the_event_please_try_again_later';error.value='';notify(message,'error')}}
function openOperations(){if(!eventForm.value.title.trim())eventForm.value.local_time=activityDateDefault();open('operations')}

defineExpose({openOperations,makeShare})
watch(sessionToken,async identity=>{generation++;working.value=false;shared.value=null;activities.value=[];clearTimeout(toastTimer);toast.value=null;close();if(!identity)return;try{await authRequest('growth/visit',{source:incoming.value?'share':'direct'})}catch{}if(sessionToken.value!==identity)return;if(props.activitiesVisible)await loadActivities();if(incoming.value&&!openedIncoming){openedIncoming=true;await showShared()}},{immediate:true})
const timer=setInterval(()=>{now.value=Date.now();if(props.activitiesVisible&&!working.value&&typeof document!=='undefined'&&document.visibilityState!=='hidden')loadActivities()},30000)
onBeforeUnmount(()=>{generation++;clearInterval(timer);clearTimeout(toastTimer);if(locked&&typeof document!=='undefined'){document.body.style.overflow=oldOverflow;document.documentElement.style.overflow=oldRootOverflow}})
</script>
<style scoped>
.growth-bar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:-10px 0 18px}.growth-tools button{display:inline-flex;align-items:center;justify-content:center;width:auto;min-height:34px;padding:7px 12px;margin:0;border:1px solid #36465b;border-radius:7px;background:#141e2b;color:#bfd0e3;font-size:12px;line-height:1.5}.growth-bar button{background:transparent;color:#b6cba3;border-color:#475b39;font-size:11px;padding:5px 10px;min-height:30px}.growth-tools .primary{background:#b9f477;color:#17230f;border-color:#b9f477;font-weight:650}.growth-tools button[disabled]{opacity:.45}.growth-tools button:focus-visible{outline:2px solid #b9f477;outline-offset:3px}.inline-hint{font-size:11px;color:#b9f477}.overlay{position:fixed;inset:0;z-index:80;display:flex;align-items:center;justify-content:center;padding:20px;background:#03070bd9;backdrop-filter:blur(8px)}.dialog{display:flex;flex-direction:column;width:100%;max-width:620px;max-height:85vh;background:#111a25;border:1px solid #35455b;border-radius:16px;box-shadow:0 24px 100px #0008;color:#e2eaf4;outline:none}.dialog-head{display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:1px solid #2b394b;font-size:16px}.dialog-head .close{font-size:22px;min-height:30px;padding:0 8px;background:none;border:0;color:#91a4bc}.dialog-body{overflow-y:auto;padding:20px;font-size:12px;line-height:1.7;overscroll-behavior:contain}.note{font-size:11px;line-height:1.8;color:#93a5bd;margin:8px 0 14px}.error{padding:9px 12px;margin-bottom:12px;background:#422731;color:#ffc0b8;border-radius:7px;font-size:12px}.growth-tools input{box-sizing:border-box;display:block;height:40px;width:100%;min-width:0;background:#0a121d;border:1px solid #37495f;border-radius:7px;color:#dbe6f3;padding:8px 11px;margin:7px 0 14px;font-size:12px}.link-input{padding:10px 12px;margin:12px 0;background:#0a121d;border:1px solid #37495f;border-radius:7px;overflow-wrap:anywhere;user-select:all;color:#bfd59f!important;opacity:1}.name{font-size:20px;font-weight:650;margin-bottom:12px}.tags{display:flex;flex-wrap:wrap;gap:5px;margin:9px 0}.tags text,.status{font-size:10px;background:#1b2a38;border:1px solid #344b60;color:#b8cee1;border-radius:5px;padding:3px 7px}.detail{margin:12px 0;color:#c7d6e7;line-height:1.9}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px}.actions .note{margin:0}.checks text{color:#badb9c;background:#b9f4770b;border-color:#b9f47726}.checks .conflict{color:#ecaaaa;background:#ecaaaa08;border-color:#ecaaaa26}.activity{padding:15px;border:1px solid #2e4054;border-radius:10px;margin:12px 0;background:#0d1621}.activity-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.activity-top b{font-size:14px}.time{font-size:12px;color:#b9cadd;margin-top:8px}.status.accent{color:#b9f477;border-color:#b9f47744;background:#b9f4770d}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px}.metrics>view{padding:13px;background:#0b141e;border:1px solid #2e3e51;border-radius:9px;display:flex;flex-direction:column;gap:5px}.metrics text,.metrics small{font-size:11px;color:#9bafc7}.metrics b{color:#b9f477;font-size:27px;font-variant-numeric:tabular-nums}.create-activity{margin:22px 0;padding-top:16px;border-top:1px solid #2d3b4e}.create-activity summary{cursor:pointer;color:#bfdc9e;margin-bottom:14px}.create-activity label{display:block;font-size:12px;color:#aebed1}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form-grid label{min-width:0}@media(max-width:500px){.overlay{padding:12px}.dialog-body{padding:16px}.dialog{max-height:90vh}.growth-bar{margin-top:-6px}}
.activity-start-field{font-size:12px;color:#aebed1}

.activities-page{margin-bottom:18px}.activities-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.activities-head>view{display:flex;align-items:center;gap:10px}.activities-head b{font-size:21px;line-height:1.5}.reservation-count{font-size:11px;color:#b9f477;background:#b9f4770d;border:1px solid #b9f47726;padding:3px 7px;border-radius:5px}.activity-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.activity-grid .activity{margin:0;padding:18px}.activities-empty{text-align:center;padding:36px 16px;border:1px dashed #34465c;border-radius:11px;color:#95a9c2;font-size:13px;margin-top:16px}@media(max-width:700px){.activity-grid{grid-template-columns:1fr}.activities-head b{font-size:19px}}
</style>
